#!/usr/bin/env -S deno run --allow-net --allow-env --allow-read --allow-write
// cc-goals.ts (D-987) — the one small file Command Centre's factory reads to see Aegis progress, READ-ONLY.
//
// CC never touches the Aegis node (blast-radius isolation is the reason this vertical has its own repo and database).
// So the progress it needs is published as a file, regenerated by the nightly coverage runner after the basket
// register and the surprise programme have run:
//   basket_understood / basket_candidates     <- research/basket.json        (basket-register.ts)
//   surprise_preregistered / _tested / _survived <- research/surprise-ledger.json (surprise-program.ts)
//   clocks_promoted / clocks_total            <- trd_forward_rules + the LATEST trd_forward_marks verdict per clock
// A clock counts as promoted only if its LATEST mark carries verdict 'promote' — never a best-ever mark (D-981: taking
// the max is survivorship applied to our own record).
// FRESHNESS (D-613): a goals file with a fresh "at" over stale inputs is the frozen-snapshot failure exactly. If either
// input is older than INPUT_MAX_H the file is NOT rewritten (its own "at" then shows its age to CC) and the run is RED.
import { declareKnobs, mkStrictRead } from "../supabase/functions/_shared/run-preconditions.ts";

const K = declareKnobs("cc-goals", [
  { name: "OUT", def: "data/cc-goals.json" },
  { name: "INPUT_MAX_H", def: "30", note: "hours; inputs older than this refuse the write" },
]);
const OWNED = Deno.env.get("OWNED_REST") || "http://localhost:33000";
const SECRET = Deno.env.get("JWT_SECRET")!;
const REPO = new URL("..", import.meta.url).pathname;
async function jwt() {
  const e = (o: unknown) => btoa(JSON.stringify(o)).replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_");
  const h = e({ alg: "HS256", typ: "JWT" }), b = e({ role: "service_role", iss: "ccg", exp: 4102444800 });
  const k = await crypto.subtle.importKey("raw", new TextEncoder().encode(SECRET), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const s = new Uint8Array(await crypto.subtle.sign("HMAC", k, new TextEncoder().encode(`${h}.${b}`)));
  return `${h}.${b}.${btoa(String.fromCharCode(...s)).replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_")}`;
}
const tok = await jwt();
const { q } = mkStrictRead(OWNED, { Authorization: `Bearer ${tok}`, apikey: tok });

async function input(rel: string) {
  const j = JSON.parse(await Deno.readTextFile(`${REPO}${rel}`)) as Record<string, any>;
  const ageH = (Date.now() - Date.parse(j.generated_at)) / 3600e3;
  if (!(ageH <= Number(K.INPUT_MAX_H))) { console.error(`!! RED ${rel} is ${ageH.toFixed(1)}h old (> ${K.INPUT_MAX_H}h) — refusing to publish stale progress as current`); Deno.exit(1); }
  return j;
}
const basket = await input("research/basket.json");
const ledger = await input("research/surprise-ledger.json");

const rules = await q(`trd_forward_rules?select=id&order=id.asc`) as { id: string }[];
if (rules.length < 1) { console.error("!! RED positive control: trd_forward_rules returned 0 clocks — the node is not answering truthfully"); Deno.exit(1); }
let promoted = 0;
for (const r of rules) {
  const m = await q(`trd_forward_marks?rule_id=eq.${encodeURIComponent(r.id)}&select=verdict&order=marked_at.desc&limit=1`) as { verdict: string | null }[];
  if (m[0]?.verdict === "promote") promoted++;
}
const goals = {
  at: new Date().toISOString(),
  basket_understood: (basket.instruments as { understood: number }[]).filter((i) => i.understood >= 0.8 - 1e-9).length,
  basket_candidates: (basket.instruments as unknown[]).length,
  surprise_preregistered: ledger.counts.preregistered as number,
  surprise_tested: ledger.counts.tested as number,
  surprise_survived: ledger.counts.survived as number,
  clocks_promoted: promoted,
  clocks_total: rules.length,
};
const out = K.OUT.startsWith("/") ? K.OUT : `${REPO}${K.OUT}`;
await Deno.mkdir(out.slice(0, out.lastIndexOf("/")), { recursive: true });
await Deno.writeTextFile(out, JSON.stringify(goals) + "\n");
console.log(`==> cc-goals ${JSON.stringify(goals)}`);
